CREATE OR REPLACE FUNCTION private.enforce_cash_register_tenant_integrity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,private AS $$ DECLARE v_register_business uuid; BEGIN IF TG_TABLE_NAME='cash_register_movements' THEN SELECT business_id INTO v_register_business FROM public.cash_registers WHERE id=NEW.cash_register_id; IF v_register_business IS NULL OR v_register_business<>NEW.business_id THEN RAISE EXCEPTION 'La caja y el movimiento deben pertenecer al mismo negocio' USING ERRCODE='foreign_key_violation'; END IF; ELSIF TG_OP='UPDATE' AND NEW.business_id<>OLD.business_id THEN RAISE EXCEPTION 'El negocio de una caja no puede cambiar' USING ERRCODE='check_violation'; END IF; RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS trg_cash_register_tenant_integrity ON public.cash_registers;
CREATE TRIGGER trg_cash_register_tenant_integrity BEFORE UPDATE ON public.cash_registers FOR EACH ROW EXECUTE FUNCTION private.enforce_cash_register_tenant_integrity();
DROP TRIGGER IF EXISTS trg_cash_register_movement_tenant_integrity ON public.cash_register_movements;
CREATE TRIGGER trg_cash_register_movement_tenant_integrity BEFORE INSERT OR UPDATE ON public.cash_register_movements FOR EACH ROW EXECUTE FUNCTION private.enforce_cash_register_tenant_integrity();
REVOKE ALL ON FUNCTION private.enforce_cash_register_tenant_integrity() FROM PUBLIC,anon,authenticated;
